<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/bootstrap.php';
requireLogin();
$type=(string)($_GET['type']??'');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);
if(!in_array($type,['lost','found'],true)||!$id){require __DIR__.'/errors/404.php';exit;}
$pdo=getDatabaseConnection();
if($type==='lost'){$sql="SELECT l.*,u.name reporter_name,c.category_name,b.building_name,d.department_name FROM lost_items l JOIN users u ON u.user_id=l.user_id JOIN categories c ON c.category_id=l.category_id LEFT JOIN buildings b ON b.building_id=l.building_id LEFT JOIN departments d ON d.department_id=b.department_id WHERE l.lost_id=:id";$ownerColumn='user_id';}
else{$sql="SELECT f.*,u.name reporter_name,c.category_name,b.building_name,d.department_name FROM found_items f JOIN users u ON u.user_id=f.finder_id JOIN categories c ON c.category_id=f.category_id LEFT JOIN buildings b ON b.building_id=f.building_id LEFT JOIN departments d ON d.department_id=b.department_id WHERE f.found_id=:id";$ownerColumn='finder_id';}
$statement=$pdo->prepare($sql);$statement->execute(['id'=>$id]);$report=$statement->fetch();if(!$report){require __DIR__.'/errors/404.php';exit;}
$date=$type==='lost'?$report['lost_date']:$report['found_date'];$isOwner=(int)$report[$ownerColumn]===(int)currentUser()['user_id'];$canEdit=$isOwner&&$report['status']==='submitted';
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title><?=e($report['item_name'])?></title><link rel="stylesheet" href="assets/css/style.css"></head><body><header class="site-header"><a class="brand brand-with-mark" href="dashboard.php"><span class="brand-mark">LU</span>Liwa University Lost & Found</a><nav><a href="search.php">Search</a><a href="my_reports.php">My Reports</a><a href="dashboard.php">Dashboard</a></nav></header><main class="detail-page"><a class="back-link" href="javascript:history.back()">← Back</a><article class="detail-card"><div><?php if($report['image_path']):?><img class="detail-image" src="<?=e($report['image_path'])?>" alt="<?=e($report['item_name'])?>"><?php else:?><div class="detail-image image-placeholder">No photo</div><?php endif;?></div><div><div class="report-meta"><span><?=e(ucfirst($type))?> report #<?=$id?></span><span class="status status-<?=e($report['status'])?>"><?=e(ucwords(str_replace('_',' ',$report['status'])))?></span></div><h1><?=e($report['item_name'])?></h1><dl class="detail-list"><dt>Category</dt><dd><?=e($report['category_name'])?></dd><dt>Date</dt><dd><?=e($date)?></dd><dt>Building</dt><dd><?=e($report['building_name']??'Not specified')?></dd><dt>Department</dt><dd><?=e($report['department_name']??'Not specified')?></dd><dt>Specific location</dt><dd><?=e($report['specific_location']??'Not specified')?></dd><dt>Reported by</dt><dd><?=e($report['reporter_name'])?></dd></dl><h2>Description</h2><p class="detail-description"><?=nl2br(e($report['description']))?></p><?php if($canEdit):?><a class="button button-primary" href="edit_report.php?type=<?=e($type)?>&id=<?=$id?>">Edit or Cancel Report</a><?php endif;?></div></article></main></body></html>
